// api/quiz/submit.js
// Public: a student submits their answers.
// Body: { c, attemptId, name, startedAt, answers: { [questionId]: value } }
// Optional header "Authorization: Bearer <supabase token>" when the student signed in with Google.
//
// Grading happens here, on the server. The attemptId is generated by the browser, so
// a double-click or retry can never create two attempts: the second call returns the first result.

import { getBearerToken, getSupabaseUser } from '../_lib/auth.js';
import { db } from '../_lib/supabase.js';
import { gradeAttempt } from '../_lib/quiz-grade.js';
import { isCode, isUuid, setCors } from '../_lib/quiz-util.js';

function cleanAnswer(q, v) {
  switch (q.type) {
    case 'single':
      return typeof v === 'string' ? v.slice(0, 40) : null;
    case 'multi':
      return Array.isArray(v)
        ? [...new Set(v.filter((x) => typeof x === 'string').map((x) => x.slice(0, 40)))].slice(0, 10)
        : null;
    case 'true_false':
      return v === true || v === 'true' ? true : v === false || v === 'false' ? false : null;
    case 'essay':
      return typeof v === 'string' ? v.slice(0, 5000) : null;
    default:
      return null;
  }
}

function correctAnswerFor(q) {
  if (q.type === 'essay') return null;
  return q.correct;
}

/** What the student is allowed to see after submitting, according to the quiz's `reveal`. */
function buildResponse(quiz, questions, attempt, answerRows) {
  const base = { ok: true, status: attempt.status };
  if (attempt.status !== 'graded' || quiz.reveal === 'none') return base;
  const out = { ...base, score: Number(attempt.score), max_score: Number(attempt.max_score) };
  if (quiz.reveal === 'full') {
    const byQ = new Map(answerRows.map((a) => [a.question_id, a]));
    out.results = questions.map((q) => {
      const a = byQ.get(q.id) || {};
      return {
        questionId: q.id,
        is_correct: a.is_correct ?? null,
        points: a.points_awarded ?? null,
        feedback: a.feedback ?? null,
        yourAnswer: a.answer ?? null,
        correctAnswer: correctAnswerFor(q),
        explanation: q.explanation || null,
      };
    });
  }
  return out;
}

export default async function handler(req, res) {
  setCors(res, 'POST, OPTIONS');
  if (req.method === 'OPTIONS') {
    res.status(204).end();
    return;
  }
  if (req.method !== 'POST') {
    res.status(405).json({ error: 'Method not allowed' });
    return;
  }

  const body = req.body && typeof req.body === 'object' ? req.body : {};
  const code = String(body.c || '').toLowerCase();
  if (!isCode(code) || !isUuid(body.attemptId)) {
    res.status(400).json({ error: 'Bad request.' });
    return;
  }
  const answersIn = body.answers && typeof body.answers === 'object' && !Array.isArray(body.answers) ? body.answers : {};

  try {
    const quizRows = await db.select('quizzes', `select=*&code=eq.${code}&is_published=eq.true&limit=1`);
    const quiz = quizRows?.[0];
    if (!quiz) {
      res.status(404).json({ error: 'This quiz is not open right now.' });
      return;
    }
    const questions = (await db.select('quiz_questions', `select=*&quiz_id=eq.${quiz.id}&order=position.asc`)) || [];

    // Already submitted (double click / retry)? Return the stored result.
    const prior = await db.select('quiz_attempts', `select=*&id=eq.${body.attemptId}&limit=1`);
    if (prior?.[0]) {
      if (prior[0].quiz_id !== quiz.id) {
        res.status(409).json({ error: 'Bad request.' });
        return;
      }
      const stored = await db.select('quiz_answers', `select=*&attempt_id=eq.${body.attemptId}`);
      res.status(200).json(buildResponse(quiz, questions, prior[0], stored || []));
      return;
    }

    // Who is this? A verified Google session wins; otherwise a typed name (unless google_only).
    let email = null;
    let authUserId = null;
    let googleName = null;
    const token = getBearerToken(req);
    if (token && quiz.identity_mode !== 'name_only') {
      const { user } = await getSupabaseUser(token);
      if (user) {
        email = user.email;
        authUserId = user.id || null;
        const meta = user.user_metadata || {};
        googleName = meta.full_name || meta.name || null;
      }
    }
    if (quiz.identity_mode === 'google_only' && !email) {
      res.status(401).json({ error: 'Please sign in with Google to take this quiz.' });
      return;
    }
    const name = String(body.name || '').trim().slice(0, 80) || (googleName ? String(googleName).slice(0, 80) : '');
    if (!name) {
      res.status(400).json({ error: 'Please enter your name.' });
      return;
    }

    // Normalise answers to known questions only.
    const cleaned = {};
    for (const q of questions) cleaned[q.id] = cleanAnswer(q, answersIn[q.id]);

    let rows;
    let score = null;
    let maxScore = 0;
    let status;
    if (quiz.auto_grade) {
      const g = gradeAttempt(questions, cleaned);
      rows = g.answers;
      score = g.score;
      maxScore = g.max_score;
      status = g.hasUngraded ? 'pending' : 'graded';
    } else {
      rows = questions.map((q) => ({
        question_id: q.id,
        answer: cleaned[q.id],
        is_correct: null,
        points_awarded: null,
        feedback: null,
      }));
      maxScore = questions.reduce((s, q) => s + (Number(q.points) || 0), 0);
      status = 'pending';
    }

    let startedAt = null;
    const t = Date.parse(body.startedAt);
    if (Number.isFinite(t) && t <= Date.now() + 60000) startedAt = new Date(t).toISOString();

    const attempt = {
      id: body.attemptId,
      quiz_id: quiz.id,
      student_name: name,
      student_email: email,
      auth_user_id: authUserId,
      started_at: startedAt,
      score,
      max_score: maxScore,
      status,
    };
    const inserted = await db.insert('quiz_attempts', [attempt]);
    try {
      await db.insert(
        'quiz_answers',
        rows.map((r) => ({
          attempt_id: body.attemptId,
          question_id: r.question_id,
          answer: r.answer,
          is_correct: r.is_correct,
          points_awarded: r.points_awarded,
          feedback: r.feedback,
        }))
      );
    } catch (err) {
      // Never leave an attempt without its answers.
      await db.delete('quiz_attempts', `id=eq.${body.attemptId}`).catch(() => {});
      throw err;
    }

    res.status(200).json(buildResponse(quiz, questions, inserted?.[0] || attempt, rows));
  } catch (err) {
    console.error('[quiz/submit]', err);
    res.status(500).json({ error: 'Could not save your answers. Please press Submit again.' });
  }
}
